    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i, j});
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    int r = cur[0];
                    int c = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = r + dRow[k];
                        int nc = c + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
