public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // validate
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // coordinates bounds
    for (int coord : start) { if (coord < 0 || coord >= n) return "cannot be travelled"; }
    for (int coord : end) { if (coord < 0 || coord >= n) return "cannot be travelled"; }

    java.util.HashMap<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] p : paths) {
        if (p == null || p.length != 4) continue;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        // bounds check
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }
        String node1 = x1 + "," + y1;
        String node2 = x2 + "," + y2;
        adj.computeIfAbsent(node1, k -> new java.util.ArrayList<>()).add(node2);
        adj.computeIfAbsent(node2, k -> new java.util.ArrayList<>()).add(node1);
    }

    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
