public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] deg=new int[n];
    for (int[] e: edges){deg[e[0]]++;deg[e[1]]++;}

    int[][] adj=new int[n][];
    for (int i=0;i<n;i++) adj[i]=new int[deg[i]];
    int[] idx=new int[n];
    for (int[] e: edges){
        adj[e[0]][idx[e[0]]++]=e[1];
        adj[e[1]][idx[e[1]]++]=e[0];
    }

    int[] time={0};

    boolean dfs(int node, int parent){
        boolean has=hasApple[node];
        for (int nei: adj[node]){
            if (nei==parent) continue;
            if (dfs(nei, node)){
                has=true;
                time[0]+=2;
            }
        }
        return has;
    }

    dfs(0,-1);
    return time[0];
}

