public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256]; // support ASCII
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (total > 0) {
        // ascending
        for (int i = 0; i < 256 && total > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char)i);
                freq[i]--;
                total--;
            }
        }
        // descending
        for (int i = 255; i >= 0 && total > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char)i);
                freq[i]--;
                total--;
            }
        }
    }
    return sb.toString();
}
