public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        switch (log) {
            case "../":
                depth = Math.max(0, depth - 1);
                break;
            case "./":
                // stay in the current directory
                break;
            default:
                // any other operation moves into a subfolder
                depth++;
                break;
        }
    }
    return depth;
}

