public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    // Handle 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    // BFS queue for generating stepping numbers
    LinkedList<Long> queue = new LinkedList<>();
    for (int start = 1; start <= 9; start++) {
        if (start <= high) {
            queue.offer((long) start);
        }
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current >= low && current <= high) {
            result.add((int) current);
        }
        if (current > high) {
            continue; // No need to generate children of a number larger than high
        }
        int lastDigit = (int) (current % 10);
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

