public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    // Use long to safely store the absolute value of Integer.MIN_VALUE
    long abs = negative ? -(long)n : n;
    String number = Long.toString(abs);
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    for (int i = number.length() - 1; i >= 0; i--) {
        sb.append(number.charAt(i));
        digitCount++;
        if (digitCount == 3 && i != 0) {
            sb.append('.');
            digitCount = 0;
        }
    }
    sb.reverse();
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

